(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-379":{scenario:{company:"Lumi Habit Studio",supervisor:{name:"Vũ Gia Bảo",role:{vi:"Trưởng bộ phận Tăng trưởng",en:"Head of Growth"}},ref_code:"EXP-4630",title:{vi:"Không nhìn trộm kết quả. Không tô đẹp CAC.",en:"No peeking at results. No flattering CAC."},brief:{vi:"Bạn rà soát biên bản tăng trưởng EXP-4630. Thử nghiệm màn hình nâng cấp Premium đăng ký trước cỡ mẫu 12000 người dùng mỗi nhóm, quyết định tại α = 0,05: ngày 4 bảng điều khiển từng báo p = 0,03, khi đủ cỡ mẫu ngày 14 thì p = 0,21. Hoàn vốn CAC tháng 10: quảng cáo 400 triệu, thưởng giới thiệu 80 triệu đồng, 1000 người trả phí mới, ARPU 50 nghìn đồng/tháng, biên lợi nhuận gộp 80% (mô phỏng). Sửa quyết định thử nghiệm và số tháng hoàn vốn, rồi lập báo cáo có căn cứ.",en:"You are reviewing growth memo EXP-4630. The Premium upgrade screen test pre-registered 12000 users per arm with a decision at alpha = 0.05: on day 4 the dashboard showed p = 0.03, at full sample on day 14 p = 0.21. October CAC payback: ads 400 million, referral rewards 80 million VND, 1000 new paying users, ARPU 50 thousand VND/month, gross margin 80% (training data). Correct the test decision and the payback months, then write an evidence-based report."},reference_title:{vi:"Đăng ký thử nghiệm & bảng kinh tế đơn vị đã duyệt · EXP-4630",en:"Approved test registration & unit economics sheet · EXP-4630"},fields:[{id:"DECISION",label:{vi:"Quyết định thử nghiệm",en:"Test decision"},initial:"SHIP-B",expected:"KEEP-A",choices:["SHIP-B","KEEP-A","EXTEND"],reference:"Phiếu đăng ký thử nghiệm",hint:{vi:"Chỉ đọc kết quả tại cỡ mẫu đã đăng ký; p ≥ 0,05 là chưa đủ bằng chứng, không kéo dài để săn ý nghĩa.",en:"Read results only at the registered sample; p >= 0.05 is not enough evidence, and do not extend to chase significance."}},{id:"PAYBACK_M",label:{vi:"Thời gian hoàn vốn CAC (tháng)",en:"CAC payback (months)"},initial:"8",expected:"12",reference:"Bảng kinh tế đơn vị tháng 10",ref_value:{vi:"Quảng cáo 400 + thưởng giới thiệu 80 (triệu đồng); 1000 khách; ARPU 50 nghìn; biên gộp 80%",en:"Ads 400 + referral rewards 80 (million VND); 1000 users; ARPU 50 thousand; gross margin 80%"},hint:{vi:"CAC phải gồm mọi chi phí thu hút, và hoàn vốn tính trên lợi nhuận gộp chứ không phải doanh thu.",en:"CAC must include every acquisition cost, and payback uses gross profit, not revenue."}}],sop32:{vi:"CAC = toàn bộ chi phí thu hút (quảng cáo + thưởng giới thiệu + khuyến mại) / số khách trả phí mới; hoàn vốn (tháng) = CAC / (ARPU tháng x biên lợi nhuận gộp).",en:"CAC = all acquisition costs (ads + referral rewards + promotions) / new paying users; payback (months) = CAC / (monthly ARPU x gross margin)."},context:{label:"GROWTH DASHBOARD / EXP-4630",metrics:[{label:{vi:"p tại cỡ mẫu đăng ký",en:"p at registered sample"},value:"0.21"},{label:{vi:"Chi phí thu hút (triệu đồng)",en:"Acquisition cost (million VND)"},value:"400 + 80"},{label:{vi:"Khách trả phí mới",en:"New paying users"},value:"1000"}]},crisis:{vi:"CEO nhắn: “Bật mặc định quyền đọc danh bạ để tự gửi lời mời đến mọi số trong máy người dùng, và giấu nút hủy gia hạn sâu trong cài đặt cho churn giảm. Quý này phải đạt chỉ tiêu.”",en:"The CEO messages you: “Turn on contact-book access by default to auto-invite every number on the user's phone, and bury the cancel-subscription button deep in settings to cut churn. We must hit this quarter's target.”"},options:{safe:{vi:"Từ chối thiết kế lừa dối người dùng, báo trưởng bộ phận Tăng trưởng và pháp chế; đề xuất giới thiệu bạn bè có đồng ý rõ ràng, nút hủy minh bạch và thử nghiệm giữ chân dựa trên giá trị.",en:"Refuse deceptive design, inform the Head of Growth and Legal; propose opt-in referrals, a transparent cancel button and value-based retention tests."},shortcut:{vi:"Bật đọc danh bạ mặc định cho một phần người dùng mới và giấu nút hủy trong một tháng thử.",en:"Enable default contact access for some new users and hide the cancel button for a one-month trial."},wait:{vi:"Không phản hồi CEO và để đội kỹ thuật tự quyết có làm hay không.",en:"Do not answer the CEO and let engineering decide whether to build it."}},questions:{vi:["Vì sao quyết định đúng là KEEP-A dù ngày 4 từng có p = 0,03? Hãy giải thích rủi ro nhìn trộm kết quả.","Trình bày cách tính thời gian hoàn vốn 12 tháng và vì sao thiết kế lừa dối làm hại tăng trưởng bền vững và tuân thủ."],en:["Why is KEEP-A correct even though day 4 showed p = 0.03? Explain the risk of peeking.","Explain how you reached the 12-month payback and why deceptive design harms sustainable growth and compliance."]},hints:{vi:["Đọc phiếu đăng ký: cỡ mẫu, ngưỡng α và thời điểm ra quyết định đã cam kết trước.","Theo SOP mục 3.2, cộng đủ chi phí thu hút rồi chia cho lợi nhuận gộp mỗi tháng của một khách.","Đọc SOP mục 4.2: thay đổi quyền riêng tư hoặc cản trở hủy dịch vụ phải qua pháp chế và được báo cáo."],en:["Read the registration: sample size, alpha threshold and the decision point committed in advance.","Per SOP 3.2, add all acquisition costs and divide by one user's monthly gross profit.","Read SOP 4.2: privacy changes or barriers to cancellation must go through Legal and be escalated."]}},learning:{summary:{vi:"Chuyên viên Marketing tăng trưởng sản phẩm kết hợp tư duy dữ liệu, thử nghiệm và tiếp thị sản phẩm để tăng người dùng, kích hoạt, giữ chân và doanh thu. Công việc gồm định vị sản phẩm, thông điệp ra mắt, tối ưu phễu AARRR, vòng lặp giới thiệu và kinh tế đơn vị. Nghề đòi hỏi thiết kế thử nghiệm đúng thống kê, đọc số liệu trung thực và tăng trưởng bằng giá trị thật thay vì thủ thuật lừa người dùng.",en:"A Growth / Product Marketing Manager combines data, experimentation and product marketing to grow acquisition, activation, retention and revenue. The work covers product positioning, launch messaging, AARRR funnel optimization, referral loops and unit economics. The role requires statistically sound tests, honest reading of numbers and growth through real value rather than tricks that mislead users."},responsibilities:{vi:["Xác định chỉ số định hướng (North Star) và cây chỉ số cho từng giai đoạn phễu AARRR.","Lập kế hoạch thử nghiệm, đăng ký giả thuyết, cỡ mẫu và tiêu chí quyết định trước khi chạy.","Xây định vị, thông điệp và kế hoạch ra mắt tính năng cùng đội sản phẩm.","Phân tích nhóm thuần tập (cohort), tỷ lệ giữ chân và kinh tế đơn vị CAC, LTV, hoàn vốn.","Thiết kế vòng lặp tăng trưởng như giới thiệu bạn bè, nội dung do người dùng tạo, tích hợp đối tác."],en:["Define the North Star metric and a metric tree for each AARRR funnel stage.","Plan experiments and pre-register hypotheses, sample sizes and decision rules.","Build positioning, messaging and feature launch plans with the product team.","Analyze cohorts, retention and unit economics: CAC, LTV and payback.","Design growth loops such as referrals, user-generated content and partner integrations."]},competencies:[{name:{vi:"Thống kê thử nghiệm",en:"Experiment statistics"},desc:{vi:"Tính cỡ mẫu, hiệu ứng tối thiểu phát hiện được, đọc p-value và tránh nhìn trộm kết quả.",en:"Compute sample size and minimum detectable effect, read p-values and avoid peeking."}},{name:{vi:"Kinh tế đơn vị",en:"Unit economics"},desc:{vi:"Tính CAC đầy đủ, LTV trên lợi nhuận gộp, thời gian hoàn vốn và biên đóng góp.",en:"Compute fully loaded CAC, gross-margin LTV, payback and contribution margin."}},{name:{vi:"Định vị & thông điệp",en:"Positioning & messaging"},desc:{vi:"Xác định khách hàng mục tiêu, phương án thay thế, giá trị khác biệt và bằng chứng.",en:"Define target customers, alternatives, differentiated value and proof points."}},{name:{vi:"Phân tích hành vi",en:"Behavioral analytics"},desc:{vi:"Dùng phễu, cohort và đường cong giữ chân để tìm điểm nghẽn kích hoạt.",en:"Use funnels, cohorts and retention curves to find activation bottlenecks."}},{name:{vi:"Tăng trưởng có đạo đức",en:"Ethical growth"},desc:{vi:"Từ chối thiết kế lừa dối, tôn trọng quyền riêng tư và quyền hủy dịch vụ của người dùng.",en:"Reject deceptive design and respect user privacy and the right to cancel."}}],knowledge:{vi:["Khung phễu AARRR (thu hút, kích hoạt, giữ chân, giới thiệu, doanh thu) và chỉ số North Star.","Thống kê A/B: giả thuyết, α, lực kiểm định, cỡ mẫu, lỗi nhìn trộm và lệch tỷ lệ phân nhóm (SRM).","Kinh tế đơn vị: CAC, LTV, thời gian hoàn vốn, tỷ lệ LTV/CAC, biên lợi nhuận gộp.","Khung định vị sản phẩm, Jobs-to-be-Done và kế hoạch ra mắt thị trường (go-to-market).","Luật Bảo vệ quyền lợi người tiêu dùng số 19/2023/QH15 và Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân."],en:["The AARRR funnel (acquisition, activation, retention, referral, revenue) and the North Star metric.","A/B statistics: hypotheses, alpha, power, sample size, peeking errors and sample ratio mismatch (SRM).","Unit economics: CAC, LTV, payback period, LTV/CAC ratio and gross margin.","Product positioning frameworks, Jobs-to-be-Done and go-to-market planning.","Consumer Rights Protection Law No. 19/2023/QH15 and Decree 13/2023/ND-CP on personal data protection."]},tools:["Công cụ phân tích sản phẩm (product analytics)","Nền tảng thử nghiệm A/B & feature flag","SQL","Python / R cho thống kê","Công cụ khảo sát người dùng","Looker Studio / BI"],kpis:{vi:["Chỉ số North Star và tỷ lệ kích hoạt người dùng mới.","Tỷ lệ giữ chân theo cohort ngày 30 và ngày 90.","Thời gian hoàn vốn CAC và tỷ lệ LTV/CAC.","Tỷ lệ thử nghiệm được đăng ký trước và kết luận đúng quy trình."],en:["The North Star metric and new-user activation rate.","Day-30 and day-90 cohort retention.","CAC payback period and LTV/CAC ratio.","Share of experiments pre-registered and concluded by the rules."]},day:[{time:"08:30",vi:"Xem bảng chỉ số North Star, phễu kích hoạt và cảnh báo lệch tỷ lệ phân nhóm.",en:"Review the North Star board, activation funnel and sample ratio alerts."},{time:"10:00",vi:"Viết phiếu đăng ký thử nghiệm mới: giả thuyết, chỉ số chính, cỡ mẫu, thời hạn.",en:"Write a new test registration: hypothesis, primary metric, sample size and duration."},{time:"13:30",vi:"Phỏng vấn 3 người dùng rời bỏ để hiểu rào cản kích hoạt.",en:"Interview 3 churned users to understand activation barriers."},{time:"15:00",vi:"Họp đội sản phẩm duyệt thông điệp ra mắt và bằng chứng giá trị.",en:"Meet the product team to approve launch messaging and proof points."},{time:"17:00",vi:"Cập nhật bảng kinh tế đơn vị, ghi bài học thử nghiệm vào kho tri thức.",en:"Update the unit economics sheet and log test learnings in the knowledge base."}],mistakes:{vi:["Dừng thử nghiệm ngay khi thấy p < 0,05 ở giữa chừng, chọn nhầm phương án do dao động ngẫu nhiên.","Tính CAC chỉ bằng chi phí quảng cáo và hoàn vốn trên doanh thu thay vì lợi nhuận gộp.","Dùng thiết kế lừa dối để tăng số liệu ngắn hạn, gây khiếu nại và rủi ro pháp lý."],en:["Stopping a test the moment p < 0.05 appears mid-way and picking noise.","Computing CAC from ad spend only and payback on revenue instead of gross profit.","Using deceptive design to inflate short-term numbers, causing complaints and legal risk."]},career:[{vi:"Chuyên viên phân tích tăng trưởng",en:"Growth Analyst"},{vi:"Chuyên viên Marketing tăng trưởng / Product Marketing",en:"Growth Marketer / Product Marketing Manager"},{vi:"Trưởng nhóm Tăng trưởng",en:"Growth Lead"},{vi:"Giám đốc Tăng trưởng / Giám đốc Marketing sản phẩm",en:"Head of Growth / Director of Product Marketing"}],glossary:[{term:"North Star Metric",vi:"Chỉ số định hướng duy nhất phản ánh giá trị cốt lõi người dùng nhận được từ sản phẩm.",en:"The single guiding metric that reflects the core value users get from the product."},{term:"Peeking",vi:"Xem và ra quyết định từ kết quả thử nghiệm nhiều lần trước khi đủ cỡ mẫu, làm tăng dương tính giả.",en:"Checking and deciding on test results repeatedly before the full sample, inflating false positives."},{term:"CAC payback",vi:"Số tháng lợi nhuận gộp từ một khách hàng cần để bù chi phí thu hút khách đó.",en:"Months of gross profit from a customer needed to recover the cost of acquiring them."},{term:"Cohort",vi:"Nhóm người dùng có cùng thời điểm hoặc điều kiện bắt đầu, dùng để phân tích giữ chân.",en:"A group of users sharing a start date or condition, used for retention analysis."},{term:"Dark pattern",vi:"Thiết kế giao diện cố ý khiến người dùng làm điều họ không định làm.",en:"Interface design that deliberately pushes users into actions they did not intend."}],quiz:[{q:{vi:"CAC 300 nghìn đồng, ARPU 60 nghìn đồng/tháng, biên lợi nhuận gộp 50%. Thời gian hoàn vốn là bao nhiêu?",en:"CAC is 300 thousand VND, ARPU 60 thousand VND/month, gross margin 50%. What is the payback period?"},options:{vi:["5 tháng","6 tháng","2,5 tháng","10 tháng"],en:["5 months","6 months","2.5 months","10 months"]},answer:3,explain:{vi:"Lợi nhuận gộp mỗi tháng = 60 x 50% = 30; hoàn vốn = 300 / 30 = 10 tháng.",en:"Monthly gross profit = 60 x 50% = 30; payback = 300 / 30 = 10 months."}},{q:{vi:"Thử nghiệm đạt đủ cỡ mẫu đăng ký với p = 0,21 tại α = 0,05. Kết luận nào đúng?",en:"A test reaches its registered sample with p = 0.21 at alpha = 0.05. Which conclusion is right?"},options:{vi:["Chưa đủ bằng chứng, giữ phương án đối chứng","Phương án mới thắng","Kéo dài đến khi p < 0,05","Bỏ ngày xấu khỏi dữ liệu"],en:["Not enough evidence, keep the control","The new variant wins","Extend until p < 0.05","Drop the bad days from the data"]},answer:0,explain:{vi:"p lớn hơn α nghĩa là chưa bác bỏ được giả thuyết không; kéo dài hay cắt dữ liệu để săn ý nghĩa là sai phương pháp.",en:"p above alpha means the null is not rejected; extending or trimming data to chase significance is invalid."}},{q:{vi:"Thử nghiệm chia 50/50 nhưng thu được 10000 và 11200 người dùng, kiểm định chi bình phương cho p < 0,001. Nên làm gì?",en:"A 50/50 test collected 10000 and 11200 users and a chi-square check gives p < 0.001. What should you do?"},options:{vi:["Đọc kết quả bình thường vì mẫu đã lớn","Dừng diễn giải, điều tra lỗi phân nhóm hoặc ghi nhận sự kiện","Xóa bớt 1200 người dùng ở nhóm lớn hơn","Chọn nhóm có nhiều người dùng hơn"],en:["Read results as usual since the sample is large","Stop interpreting and investigate assignment or logging bugs","Delete 1200 users from the larger arm","Pick the arm with more users"]},answer:1,explain:{vi:"Đây là lệch tỷ lệ phân nhóm (SRM), dấu hiệu lỗi phân bổ hoặc đo lường; kết quả không đáng tin cho đến khi tìm ra nguyên nhân.",en:"This is a sample ratio mismatch (SRM), a sign of assignment or tracking bugs; results are untrustworthy until the cause is found."}},{q:{vi:"CEO yêu cầu giấu nút hủy gia hạn để giảm churn. Bạn làm gì?",en:"The CEO asks you to hide the cancel button to reduce churn. What do you do?"},options:{vi:["Làm theo trong một quý","Chỉ giấu trên ứng dụng di động","Từ chối, báo pháp chế và đề xuất giữ chân bằng giá trị","Làm nhưng không ghi vào tài liệu"],en:["Comply for one quarter","Hide it on mobile only","Refuse, inform Legal and propose value-based retention","Do it but keep it undocumented"]},answer:2,explain:{vi:"Cản trở quyền hủy là thiết kế lừa dối, xâm phạm quyền lợi người tiêu dùng; giữ chân phải bằng giá trị thật.",en:"Obstructing cancellation is a dark pattern that harms consumer rights; retention must come from real value."}}],tools_en:["Product analytics tool","A/B testing & feature flag platform","SQL","Python / R for statistics","User survey tool","Looker Studio / BI"]}}})})(window.KKR);
